import { mkdtempSync, readFileSync, rmSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { generateIconTypes, writeIfChanged } from '../types'

describe('given icon names', () => {
  describe('when their types are generated', () => {
    it('then they augment the names of maz-ui, sorted and without duplicates', () => {
      expect(generateIconTypes(['x-mark', 'app:hero', 'x-mark'])).toBe([
        '// Generated by MazUi() of @maz-ui/vite-plugin, do not edit',
        'import type {} from \'maz-ui\'',
        '',
        'declare module \'maz-ui\' {',
        '  interface MazIconNames {',
        '    \'app:hero\': true',
        '    \'x-mark\': true',
        '  }',
        '}',
        '',
      ].join('\n'))
    })
  })

  describe('when their types are generated in strict mode', () => {
    it('then the strict option is augmented too', () => {
      expect(generateIconTypes(['x-mark'], { strict: true })).toContain('  interface MazIconOptions {\n    strict: true\n  }\n}')
    })
  })
})

describe('given a file of types', () => {
  let dir: string

  beforeAll(() => {
    dir = mkdtempSync(join(tmpdir(), 'maz-types-'))
  })

  afterAll(() => {
    rmSync(dir, { recursive: true, force: true })
  })

  describe('when it is written in a new folder', () => {
    it('then it is created', () => {
      const file = join(dir, 'src/maz-icons.d.ts')

      expect(writeIfChanged(file, 'a')).toBe(true)
      expect(readFileSync(file, 'utf8')).toBe('a')
    })
  })

  describe('when it is written with the same content', () => {
    it('then it is not written again', () => {
      const file = join(dir, 'same.d.ts')
      writeIfChanged(file, 'a')

      expect(writeIfChanged(file, 'a')).toBe(false)
    })
  })

  describe('when it is written with a new content', () => {
    it('then it is replaced', () => {
      const file = join(dir, 'changed.d.ts')
      writeIfChanged(file, 'a')

      expect(writeIfChanged(file, 'b')).toBe(true)
      expect(readFileSync(file, 'utf8')).toBe('b')
    })
  })
})
